create role anon; create role authenticated; create role service_role;
create table public.email_report_tbl("user_id" uuid not null,"total_count" integer not null,"valid_count" integer not null,"invalid_count" integer not null,"risky_count" integer not null,"restricted_count" integer not null,"suppressed_count" integer,"organization_id" uuid,"workspace_id" uuid,"updated_at" timestamp with time zone default now() not null);
