CREATE INDEX email_report_tbl_tenant_idx ON public.email_report_tbl USING btree (organization_id, workspace_id);
CREATE UNIQUE INDEX email_report_tbl_workspace_unique ON public.email_report_tbl USING btree (user_id, organization_id, workspace_id) NULLS NOT DISTINCT;
create table public.emails_historical_performance("id" bigint generated by default as identity not null,"created_at" timestamp with time zone default now() not null,"month" text,"year" integer,"key" text,"start" timestamp with time zone,"end" timestamp with time zone,"valid" integer default 0,"invalid" integer default 0,"risky" integer default 0,"restricted" integer default 0,"order_id" integer default 0,"user_id" uuid,"organization_id" uuid,"workspace_id" uuid);
alter table public.emails_historical_performance add constraint "emails_historical_performance_pkey" PRIMARY KEY (id);
CREATE INDEX emails_historical_performance_tenant_idx ON public.emails_historical_performance USING btree (organization_id, workspace_id);
CREATE UNIQUE INDEX emails_historical_performance_workspace_unique ON public.emails_historical_performance USING btree (user_id, organization_id, workspace_id, order_id) NULLS NOT DISTINCT;
create table public.email_usage_monthly("month_start" date not null,"user_id" uuid not null,"valid_count" integer default 0 not null,"invalid_count" integer default 0 not null,"risky_count" integer default 0 not null,"restricted_count" integer default 0 not null,"suppressed_count" integer default 0 not null,"updated_at" timestamp with time zone default now() not null,"sort_idx" smallint,"organization_id" uuid,"workspace_id" uuid);
alter table public.email_usage_monthly add constraint "email_usage_monthly_pk" PRIMARY KEY (month_start, user_id);
CREATE INDEX email_usage_monthly_tenant_idx ON public.email_usage_monthly USING btree (organization_id, workspace_id);
CREATE UNIQUE INDEX email_usage_monthly_workspace_unique ON public.email_usage_monthly USING btree (month_start, user_id, organization_id, workspace_id) NULLS NOT DISTINCT;
CREATE INDEX i_email_usage_monthly_user_sort ON public.email_usage_monthly USING btree (user_id, sort_idx);
create table public.email_usage_breakdown_monthly("month_start" date not null,"user_id" uuid not null,"metric" text not null,"key" text not null,"count" integer default 0 not null,"updated_at" timestamp with time zone default now() not null,"sort_idx" smallint,"color_hex" text,"organization_id" uuid,"workspace_id" uuid);
alter table public.email_usage_breakdown_monthly add constraint "email_usage_breakdown_monthly_pk" PRIMARY KEY (month_start, user_id, metric, key);
CREATE INDEX email_usage_breakdown_monthly_metric_idx ON public.email_usage_breakdown_monthly USING btree (metric);
CREATE INDEX email_usage_breakdown_monthly_month_start_idx ON public.email_usage_breakdown_monthly USING btree (month_start);
CREATE INDEX email_usage_breakdown_monthly_tenant_idx ON public.email_usage_breakdown_monthly USING btree (organization_id, workspace_id);
CREATE INDEX email_usage_breakdown_monthly_user_id_idx ON public.email_usage_breakdown_monthly USING btree (user_id);
CREATE UNIQUE INDEX email_usage_breakdown_monthly_workspace_unique ON public.email_usage_breakdown_monthly USING btree (month_start, user_id, organization_id, workspace_id, metric, key) NULLS NOT DISTINCT;
CREATE INDEX i_eubm_user_metric_sort ON public.email_usage_breakdown_monthly USING btree (user_id, metric, sort_idx);
create table public.emails("id" bigint generated by default as identity not null,"created_at" timestamp with time zone default now() not null,"email" text not null,"corrected_email" text,"user_id" uuid not null,"segment_id" text,"klaviyo_account_id" uuid,"klaviyo_profile_id" text,"status" text,"substatus" text,"check_status" boolean,"did_you_mean" text,"attempts" integer default 0,"last_run" timestamp with time zone,"suppress" boolean default false not null,"tagged" boolean default false not null,"lh_status" text,"lh_category" text,"job_step" text,"job_status" text,"job_timestamp" timestamp with time zone,"external_created_at" timestamp with time zone,"attempts_record" jsonb default '[]'::jsonb not null,"merged" boolean default false not null,"updated" boolean,"typo_fixed" boolean default false not null,"leading_period_email" text,"organization_id" uuid,"workspace_id" uuid,"updated_at" timestamp with time zone default now() not null,"checked_at" timestamp with time zone);
alter table public.emails add constraint "emails_pkey" PRIMARY KEY (id);
alter table public.emails add constraint "unique_email_user_profile_klaviyo" UNIQUE (email, user_id, klaviyo_profile_id, klaviyo_account_id);
CREATE INDEX emails_tenant_idx ON public.emails USING btree (organization_id, workspace_id);
CREATE INDEX emails_user_id_created_at_idx ON public.emails USING btree (user_id, created_at);
CREATE INDEX emails_user_id_created_at_lh_category_idx ON public.emails USING btree (user_id, created_at, lh_category);
CREATE INDEX emails_updated_at_idx ON public.emails USING btree (updated_at);
create table public.klaviyo_accounts("id" uuid default gen_random_uuid() not null,"created_at" timestamp with time zone default now() not null,"user_id" uuid,"access_token" text,"refresh_token" text,"account_details" json,"active" boolean,"segments" jsonb,"selected_segment" jsonb,"fix_typos" boolean default true not null,"full_mailbox_retries" integer default 12 not null,"mail_error_retries" integer default 3 not null,"connection_name" text,"token_expires_in" timestamp with time zone,"token_scope" text,"greylisted_retries" integer default 3,"exception_occurred_retries" integer default 3,"mail_server_temporary_error_retries" integer default 3,"unexpected_error_retries" integer default 3,"organization_id" uuid,"workspace_id" uuid,"created_by_user_id" uuid,"billing_user_id" uuid,"external_account_id" text);
alter table public.klaviyo_accounts add constraint "klaviyo_accounts_pkey" PRIMARY KEY (id);
CREATE INDEX klaviyo_accounts_tenant_idx ON public.klaviyo_accounts USING btree (organization_id, workspace_id, active);
CREATE UNIQUE INDEX klaviyo_accounts_active_external_account_unique ON public.klaviyo_accounts USING btree (external_account_id) WHERE ((active = true) AND (external_account_id IS NOT NULL));
create table public.stripe_accounts("id" bigint generated by default as identity not null,"created_at" timestamp with time zone default now() not null,"user_id" uuid not null,"customer_id" text,"subscription_id" text,"plan_id" text,"active" boolean default true not null,"reset_date" date,"credits_plan" integer default 0 not null,"credits_used" integer default 0 not null,"credits_remaining" integer default 0 not null,"trial_plan" integer default 0 not null,"trial_used" integer default 0 not null,"trial_remaining" integer default 0 not null,"overage_plan" integer default 0 not null,"overage_used" integer default 0 not null,"overage_remaining" integer default 0 not null,"credits_turnover" integer default 0,"trial_redeemed_with" uuid,"organization_id" uuid,"workspace_id" uuid,"billing_scope" text default 'user'::text not null,"updated_at" timestamp with time zone default now() not null);
alter table public.stripe_accounts add constraint "stripe_accounts_billing_scope_check" CHECK ((billing_scope = ANY (ARRAY['user'::text, 'workspace'::text])));
alter table public.stripe_accounts add constraint "stripe_accounts_pkey" PRIMARY KEY (id);
CREATE INDEX stripe_accounts_customer_idx ON public.stripe_accounts USING btree (customer_id) WHERE (customer_id IS NOT NULL);
CREATE INDEX stripe_accounts_user_workspace_idx ON public.stripe_accounts USING btree (user_id, workspace_id);
CREATE INDEX stripe_accounts_workspace_idx ON public.stripe_accounts USING btree (workspace_id) WHERE (workspace_id IS NOT NULL);
CREATE UNIQUE INDEX stripe_accounts_one_active_workspace_customer ON public.stripe_accounts USING btree (workspace_id) WHERE ((active = true) AND (workspace_id IS NOT NULL));
CREATE UNIQUE INDEX stripe_accounts_workspace_scope_active_unique ON public.stripe_accounts USING btree (user_id, workspace_id) WHERE ((active = true) AND (workspace_id IS NOT NULL) AND (billing_scope = 'workspace'::text));
CREATE UNIQUE INDEX stripe_accounts_user_scope_active_unique ON public.stripe_accounts USING btree (user_id, billing_scope) WHERE ((active = true) AND (workspace_id IS NULL) AND (billing_scope = 'user'::text));
create table public.stripe_webhook_events("event_id" text not null,"event_type" text not null,"status" text default 'processing'::text not null,"attempts" integer default 1 not null,"error_message" text,"created_at" timestamp with time zone default now() not null,"updated_at" timestamp with time zone default now() not null,"processed_at" timestamp with time zone);
alter table public.stripe_webhook_events add constraint "stripe_webhook_events_pkey" PRIMARY KEY (event_id);
alter table public.stripe_webhook_events add constraint "stripe_webhook_events_status_check" CHECK ((status = ANY (ARRAY['processing'::text, 'processed'::text, 'failed'::text])));
create table public.credit_history("id" uuid default gen_random_uuid() not null,"user_id" uuid not null,"change" integer not null,"reason" text,"context" text,"created_at" timestamp with time zone default now(),"remaining" integer,"organization_id" uuid,"workspace_id" uuid,"klaviyo_account_id" uuid,"source" text,"description" text,"idempotency_key" text,"credits_delta" integer,"credits_remaining" integer);
alter table public.credit_history add constraint "credit_history_pkey" PRIMARY KEY (id);
CREATE INDEX credit_history_tenant_idx ON public.credit_history USING btree (organization_id, workspace_id);
CREATE UNIQUE INDEX credit_history_idempotency_key_unique ON public.credit_history USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL);
create table public.bulk_jobs("id" uuid default gen_random_uuid() not null,"user_id" text not null,"account_id" text not null,"segment_id" text not null,"profiles" jsonb not null,"profile_count" integer not null,"stripe_invoice_id" text,"stripe_invoice_url" text,"amount_cents" integer not null,"rate_cents" numeric not null,"status" text default 'pending_payment'::text,"autostart" boolean default false,"created_at" timestamp with time zone default now(),"paid_at" timestamp with time zone,"started_at" timestamp with time zone,"completed_at" timestamp with time zone,"processed_count" integer default 0,"job_name" text,"job_description" text,"platform_name" text default 'Klaviyo'::text,"user_email" text,"segment_snapshot" jsonb,"account_snapshot" jsonb,"organization_id" uuid,"workspace_id" uuid,"billing_user_id" uuid);
alter table public.bulk_jobs add constraint "bulk_jobs_pkey" PRIMARY KEY (id);
CREATE INDEX bulk_jobs_tenant_idx ON public.bulk_jobs USING btree (organization_id, workspace_id);
create table public.bulk_emails("id" integer generated by default as identity not null,"bulk_job_id" uuid,"email" text not null,"profile_id" text not null,"account_id" text not null,"user_id" text not null,"segment_id" text,"status" text,"substatus" text,"did_you_mean" text,"lh_status" text,"lh_category" text,"attempts" integer default 0,"check_status" boolean default false,"tagged" boolean default false,"suppress" boolean default false,"created_at" timestamp with time zone default now(),"validated_at" timestamp with time zone,"organization_id" uuid,"workspace_id" uuid,"merged" boolean default false not null,"typo_fixed" boolean default false not null,"attempts_record" jsonb default '[]'::jsonb not null,"klaviyo_profile_id" text,"leading_period_email" text);
alter table public.bulk_emails add constraint "bulk_emails_pkey" PRIMARY KEY (id);
CREATE INDEX bulk_emails_tenant_idx ON public.bulk_emails USING btree (organization_id, workspace_id);
create table public.bulk_job_reports("id" uuid default gen_random_uuid() not null,"bulk_job_id" uuid not null,"report_type" text not null,"version" integer default 1 not null,"data" jsonb not null,"generated_at" timestamp with time zone default now() not null,"organization_id" uuid,"workspace_id" uuid);
alter table public.bulk_job_reports add constraint "bulk_job_reports_bulk_job_id_report_type_version_key" UNIQUE (bulk_job_id, report_type, version);
alter table public.bulk_job_reports add constraint "bulk_job_reports_pkey" PRIMARY KEY (id);
CREATE INDEX idx_bulk_job_reports_job_id ON public.bulk_job_reports USING btree (bulk_job_id);
CREATE INDEX idx_bulk_job_reports_type ON public.bulk_job_reports USING btree (report_type);
create table public.stripe_payment_methods("id" bigint generated by default as identity not null,"customer_id" text not null,"payment_id" text,"type" text,"brand" text,"last4" integer,"exp_month" integer,"exp_year" integer,"active" boolean,"is_expired" boolean,"is_default" boolean,"user_id" uuid,"organization_id" uuid,"workspace_id" uuid,"billing_scope" text default 'user'::text not null);
alter table public.stripe_payment_methods add constraint "stripe_payment_methods_billing_scope_check" CHECK ((billing_scope = ANY (ARRAY['user'::text, 'workspace'::text])));
alter table public.stripe_payment_methods add constraint "stripe_payment_methods_pkey" PRIMARY KEY (id);
